<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pdo=db();$bid=branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['save'])){$id=(int)($_POST['id']??0);$name=trim($_POST['name']);if($id)$pdo->prepare('UPDATE categories SET name=? WHERE id=? AND branch_id=?')->execute([$name,$id,$bid]);else $pdo->prepare('INSERT INTO categories(name,branch_id) VALUES(?,?)')->execute([$name,$bid]);flash('success','Kategori disimpan.');}if(isset($_POST['delete'])){try{$pdo->prepare('DELETE FROM categories WHERE id=? AND branch_id=?')->execute([(int)$_POST['delete'],$bid]);flash('success','Kategori dihapus.');}catch(PDOException){flash('error','Kategori masih digunakan produk.');}}redirect('/owner/kategori.php');}
$s=$pdo->prepare('SELECT c.*,COUNT(p.id) total FROM categories c LEFT JOIN products p ON p.category_id=c.id WHERE c.branch_id=? GROUP BY c.id ORDER BY c.name');$s->execute([$bid]);$rows=$s->fetchAll();$pageTitle='Kategori Produk';$active='kategori';include __DIR__.'/../includes/header.php';?>
<div class="grid two-col"><section class="card"><h2>Tambah kategori</h2><form method="post" style="margin-top:16px"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Nama kategori<input name="name" required></label><button class="btn primary" name="save" style="margin-top:14px">Simpan</button></form></section><section class="card"><h2>Daftar kategori cabang</h2><table class="table"><tbody><?php foreach($rows as $c):?><tr><td><?=e($c['name'])?></td><td><?=$c['total']?> produk</td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button class="btn danger sm" name="delete" value="<?=$c['id']?>">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></section></div><?php include __DIR__.'/../includes/footer.php';?>
